// Two open-ended classroom games. Photos stay in this page; no model or upload API.
const gameSamples=['lushan','gorges','xihu','lotus','plum','snow','desert','moon'];
const gameDraft=()=>({workId:null,photo:null,quote:'',reason:'',difference:''});
const poetryGame={mode:'poem',drafts:{poem:{...gameDraft(),workId:'lb-lushan'},photo:gameDraft()},cards:[],imageRequest:0};
function gameWorks(){return getReadingWorks().filter(w=>readingCategory(w)==='诗词曲'&&w.meta.kind!=='戏曲');}
function gameSearchWorks(query){const terms=query.trim().split(/\s+/).filter(Boolean);return gameWorks().filter(w=>terms.every(t=>[w.s[5],workAuthor(w),w.s[6]].some(s=>s.includes(t))));}
function gameImageUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function gameQuoteMatches(text,quote){const clean=s=>s.normalize('NFKC').replace(/[\p{P}\p{Z}\s]/gu,'');const q=clean(quote);return q.length>=4&&clean(text).includes(q);}
function currentGame(){return poetryGame.drafts[poetryGame.mode];}
function gameMessage(text){$('gameMessage').textContent=text;}
function captureGameDraft(){const d=currentGame();if($('gameQuote'))d.quote=$('gameQuote').value;if($('gameReason'))d.reason=$('gameReason').value;if($('gameDifference'))d.difference=$('gameDifference').value;if(d.photo&&$('gameCredit')&&!$('gameCredit').readOnly){d.photo.credit=$('gameCredit').value;d.photo.kind=$('gameOrigin').value;}}
function gameWorkOptions(query=''){const works=gameSearchWorks(query),d=currentGame();$('gameWork').innerHTML='<option value="">选择一首诗词…</option>'+works.map(w=>`<option value="${w.meta.id}">${escapeHtml(workAuthor(w)+' · '+w.s[5])}</option>`).join('');if(works.some(w=>w.meta.id===d.workId))$('gameWork').value=d.workId;else if(d.workId){const w=findReadingWork(d.workId);$('gameWork').insertAdjacentHTML('beforeend',`<option value="${d.workId}">${escapeHtml(workAuthor(w)+' · '+w.s[5])}（当前选择）</option>`);$('gameWork').value=d.workId;}$('gameSearchCount').textContent=`${works.length} 首匹配 · 诗词库参考，非地区必考清单`;}
function renderGamePoem(){const w=findReadingWork(currentGame().workId);$('gamePoem').innerHTML=w?`<h3>${escapeHtml(w.s[5])}</h3><small>${escapeHtml(workAuthor(w))} · ${escapeHtml(w.meta.stage)} · ${escapeHtml(w.meta.scope)}</small><div class="game-poem-text">${escapeHtml(w.s[6])}</div><div class="game-line-picks">${w.s[6].split('\n').filter(Boolean).slice(0,8).map((line,i)=>`<button data-game-line="${i}">${escapeHtml(line.slice(0,90))}</button>`).join('')}</div><small>点一句，放入下方“诗句依据”；也可以自己摘录。</small><details><summary>观察提示</summary><p>${escapeHtml(w.meta.focus)}</p><p>${escapeHtml(w.s[10])}</p></details>`:'<div class="game-empty"><strong>先观察图片，再寻找诗句</strong><p>从颜色、景物、季节或情绪出发，搜索诗句，选一首最有话可说的。</p></div>';
 document.querySelectorAll('[data-game-line]').forEach(b=>b.onclick=()=>{const w=findReadingWork(currentGame().workId);$('gameQuote').value=w.s[6].split('\n').filter(Boolean)[+b.dataset.gameLine].slice(0,140);currentGame().quote=$('gameQuote').value;});}
function renderGamePhoto(){const p=currentGame().photo;$('gameImagePreview').innerHTML=p?`<img src="${escapeHtml(p.src)}" alt="${escapeHtml(p.title)}" referrerpolicy="no-referrer"><p><strong>${escapeHtml(p.title)}</strong><small>${escapeHtml(p.kind)} · 可从构图、季节、光线与情绪观察</small></p>`:'<div class="game-empty"><span>▧</span><strong>为诗句找一幅画面</strong><p>可以用手机照片、网络图片，或自己在其他工具生成的图片。</p></div>';
 const fixed=p?.origin==='sample'||p?.origin==='ai-sample';$('gameOrigin').disabled=!p||fixed;$('gameOrigin').value=p?.kind||'自己拍摄';$('gameCredit').value=p?.credit||'';$('gameCredit').readOnly=!p||fixed;$('gameCredit').placeholder=p?'写明作者、网址或AI工具；自己拍的可写拍摄地点。':'选择图片后填写来源';
 const img=$('gameImagePreview').querySelector('img');if(img)img.onerror=()=>{img.hidden=true;gameMessage('图片未能显示，请换一张图片；网络图片可先保存到手机，再用“上传图片”。');};}
function useGameSample(id){captureGameDraft();poetryGame.imageRequest++;const d=currentGame();if(id==='ai'){d.photo={src:'assets/films/lushan-poster.jpg',title:'瀑布与银河 · AI诗境示例',origin:'ai-sample',kind:'AI生成',credit:'本站内置AI情境插画，仅作艺术想象；不是实时生成，也不是庐山实景。'};}else{const a=poemImageAssets[id];if(!a)return;d.photo={src:a.src,title:a.title,origin:'sample',kind:'内置示例',credit:`${a.type}；${a.author}；${a.license}；${a.source}`};}renderGamePhoto();gameMessage('图片已选好。找到诗句依据，说明它们怎样呼应，也可以指出不同。');}
function renderPoetryGames(){const d=currentGame(),photoFirst=poetryGame.mode==='photo';
 $('gamesPanel').innerHTML=`<div class="games-heading"><div><p class="eyebrow">两种方向，同一种发现</p><h2>让诗和照片，互相说话</h2><p>没有唯一答案。把配对的理由说清楚，比“猜中”更重要。</p></div><span class="game-free">不消耗 Token</span></div><div class="game-modes" role="group" aria-label="诗图小游戏玩法"><button data-game-mode="poem" aria-pressed="${!photoFirst}"><b>诗 → 图</b><strong>给古诗配照片</strong><small>读一首诗，寻找你眼中的画面。</small></button><button data-game-mode="photo" aria-pressed="${photoFirst}"><b>图 → 诗</b><strong>给照片配古诗</strong><small>看一张图，挑选能与它对话的诗句。</small></button></div><p class="game-local-note">手机照片只在本页处理，不上传服务器；网络图片由浏览器向原站加载。作品墙仅留在当前页面，离开前请下载作品卡。AI图片可上传并标明来源，本站不实时生成。</p><p id="gameMessage" class="game-message" role="status" aria-live="polite"></p><div class="game-workspace ${photoFirst?'photo-first':''}"><section class="game-poem-side"><div class="game-step"><span>${photoFirst?'02':'01'}</span><h3>${photoFirst?'哪一句，能为画面发声？':'先读一首诗'}</h3><button id="gameRandomPoem">换首诗 · 新一轮 ↻</button></div><label for="gameSearch">找诗：作者、篇名或诗句</label><input id="gameSearch" type="search" maxlength="80" placeholder="试试：月、江、李白、山重水复"><p id="gameSearchCount" class="game-small"></p><label class="sr-only" for="gameWork">配对诗词</label><select id="gameWork"></select><article id="gamePoem"></article></section><section class="game-photo-side"><div class="game-step"><span>${photoFirst?'01':'02'}</span><h3>${photoFirst?'先观察一张照片':'为诗句找画面'}</h3></div><div id="gameImagePreview" class="game-image-preview"></div><div class="game-image-inputs"><label class="game-upload" for="gameFile">＋ 上传手机照片 / AI图片<input id="gameFile" class="sr-only" type="file" accept="image/*"></label><p class="game-small">单张不超过20MB；支持浏览器可读取的图片。HEIC若无法打开，请先导出为JPG。</p><div class="game-url-row"><label class="sr-only" for="gameImageUrl">网络图片直链</label><input id="gameImageUrl" type="url" placeholder="粘贴 https:// 图片直链"><button id="gameLoadUrl">加载图片</button></div><details class="game-samples" ${!d.photo?'open':''}><summary>先用一张内置示例</summary><div>${gameSamples.map(id=>`<button data-game-sample="${id}" title="${escapeHtml(poemImageAssets[id].title)}"><img src="${poemImageAssets[id].src}" alt="${escapeHtml(poemImageAssets[id].title)}" loading="lazy"></button>`).join('')}<button data-game-sample="ai" class="game-ai-sample">AI诗境<br><small>内置示例</small></button></div></details><div class="game-source-fields"><label>图片类型<select id="gameOrigin"><option>自己拍摄</option><option>网上找到</option><option>AI生成</option><option disabled>内置示例</option></select></label><label>作者 / 来源说明<input id="gameCredit" maxlength="500"></label></div><p class="game-small">网上找图请保留作者与来源；分享前确认可以使用。内置示例保留原有署名。</p></div></section></div><form id="gamePairForm" class="game-reflection"><div><p class="eyebrow">最后一步 · 让配对站得住脚</p><h3>你为什么把它们放在一起？</h3></div><label for="gameQuote">诗句依据 <small>摘录一处连续诗句，至少4字；可点击原文快速填入。</small></label><input id="gameQuote" maxlength="140" value="${escapeHtml(d.quote)}" placeholder="例如：飞流直下三千尺，疑是银河落九天。" required><label for="gameReason">配对理由 <small>至少12字：点出图片细节，并联系诗句。</small></label><textarea id="gameReason" maxlength="600" rows="3" placeholder="我看到图片里的……，想到诗句中的……，因为……" required>${escapeHtml(d.reason)}</textarea><label for="gameDifference">不同之处 / 我的想象 <small>可选，真实景物和诗意想象也可以不同。</small></label><textarea id="gameDifference" maxlength="300" rows="2" placeholder="照片是今天拍的；诗里的……是想象，照片里没有……">${escapeHtml(d.difference)}</textarea><div class="game-submit-row"><p>只核对诗句摘录与填写完整度，不使用AI评分。</p><button class="studio-primary" type="submit">完成配对，做成作品卡 →</button></div></form><section class="game-wall"><div><p class="eyebrow">本轮作品墙 · 最多12张</p><h3>带着诗句，邀请同学来聊聊 <span id="gameCardCount"></span></h3><p>下载的HTML作品卡可离线打开；使用网络直链的图片仍需联网。</p></div><div id="gameCards" class="game-cards"></div></section>`;
 if(photoFirst){const grid=$('gamesPanel').querySelector('.game-workspace');grid.insertBefore(grid.querySelector('.game-photo-side'),grid.firstElementChild);}
 document.querySelectorAll('[data-game-mode]').forEach(b=>b.onclick=()=>{captureGameDraft();poetryGame.imageRequest++;poetryGame.mode=b.dataset.gameMode;renderPoetryGames();});gameWorkOptions();renderGamePoem();renderGamePhoto();renderGameCards();
 $('gameSearch').oninput=()=>gameWorkOptions($('gameSearch').value);$('gameWork').onchange=()=>{captureGameDraft();d.workId=$('gameWork').value||null;d.quote='';$('gameQuote').value='';renderGamePoem();};
 $('gameRandomPoem').onclick=()=>{const works=gameWorks().filter(w=>w.featured&&w.meta.id!==d.workId);d.workId=works[Math.floor(Math.random()*works.length)].meta.id;d.quote='';d.reason='';d.difference='';renderPoetryGames();gameMessage('新一轮：诗已更换，图片保留。请重新找出配对依据。');};
 document.querySelectorAll('[data-game-sample]').forEach(b=>b.onclick=()=>useGameSample(b.dataset.gameSample));$('gameOrigin').onchange=()=>{captureGameDraft();renderGamePhoto();};$('gameCredit').oninput=()=>captureGameDraft();$('gameFile').onchange=loadGameFile;$('gameLoadUrl').onclick=loadGameUrl;$('gamePairForm').onsubmit=e=>{e.preventDefault();completeGamePair();};
}
function loadGameImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.referrerPolicy='no-referrer';image.onload=()=>resolve(image);image.onerror=()=>reject(Error('浏览器无法读取这张图片。请换成JPG、PNG、WEBP等格式，或将网络图片保存后再上传。'));image.src=src;});}
function resizeGameImage(image){const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fffdf8';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.84);}
async function loadGameFile(e){const file=e.target.files[0];if(!file)return;const request=++poetryGame.imageRequest,d=currentGame();captureGameDraft();let objectUrl;
 try{if(!file.type.startsWith('image/'))throw Error('请选择图片文件。');if(file.size>20*1024*1024)throw Error('图片超过20MB，请先压缩后再选择。');objectUrl=URL.createObjectURL(file);const image=await loadGameImage(objectUrl);if(request!==poetryGame.imageRequest)return;d.photo={src:resizeGameImage(image),title:file.name.slice(0,100),origin:'upload',kind:'自己拍摄',credit:''};renderGamePhoto();gameMessage('图片已在本页缩小处理，未上传服务器。如果来自AI或网络，请修改图片类型并补充来源。');}catch(error){if(request===poetryGame.imageRequest)gameMessage(error.message);}finally{if(objectUrl)URL.revokeObjectURL(objectUrl);e.target.value='';}}
async function loadGameUrl(){const src=gameImageUrl($('gameImageUrl').value.trim());if(!src){gameMessage('请填写以 https:// 开头的图片直链，不是网页地址；也可以把图片保存后上传。');return;}const request=++poetryGame.imageRequest,d=currentGame();captureGameDraft();gameMessage('正在从图片原站加载…');
 try{await loadGameImage(src);if(request!==poetryGame.imageRequest)return;d.photo={src,title:'我找到的网络图片',origin:'url',kind:'网上找到',credit:src};renderGamePhoto();gameMessage('网络图片已加载。请保留作者与来源，再选择诗句说明理由。');}catch(error){if(request===poetryGame.imageRequest)gameMessage(error.message);}}
function validateGamePair(d){const w=findReadingWork(d.workId);if(!w||readingCategory(w)!=='诗词曲')return '请先选择一首诗词。';if(!d.photo)return '请上传、加载或选择一张示例图。';if(!gameQuoteMatches(w.s[6],d.quote))return '诗句依据需取自当前原文，至少4字；请摘录一处连续诗句，也可以点击原文快速填入。';if(d.reason.trim().length<12)return '请用至少12个字，联系图片细节与诗句解释配对理由。';if(!d.photo.credit.trim())return '请补充图片来源：自己拍摄可写地点，AI图片写工具，网络图片写作者或网址。';return '';}
function completeGamePair(){captureGameDraft();const d=currentGame(),error=validateGamePair(d);if(error){gameMessage(error);$('gameMessage').scrollIntoView({behavior:'smooth',block:'center'});return;}if(poetryGame.cards.length>=12){gameMessage('本轮最多保存12张作品卡。请先下载，再移除一张后继续。');return;}poetryGame.cards.unshift({...d,photo:{...d.photo},mode:poetryGame.mode,id:crypto.randomUUID()});renderGameCards();gameMessage('配对已整理成作品卡！邀请同学说出一处呼应，再问一个问题。作品不会自动上传或发布。');$('gameCards').scrollIntoView({behavior:'smooth',block:'start'});}
function renderGameCards(){$('gameCardCount').textContent=`（${poetryGame.cards.length}张）`;$('gameCards').innerHTML=poetryGame.cards.length?poetryGame.cards.map(c=>{const w=findReadingWork(c.workId);return `<article><img src="${escapeHtml(c.photo.src)}" alt="${escapeHtml(c.photo.title)}" referrerpolicy="no-referrer"><div><small>${c.mode==='poem'?'给诗配图':'给图配诗'} · ${escapeHtml(c.photo.kind)}</small><h4>${escapeHtml(w.s[5])} <small>${escapeHtml(workAuthor(w))}</small></h4><blockquote>${escapeHtml(c.quote)}</blockquote><p>${escapeHtml(c.reason)}</p>${c.difference?`<p class="game-small">不同与想象：${escapeHtml(c.difference)}</p>`:''}<details><summary>图片来源与交流问题</summary><p>${escapeHtml(c.photo.credit)}</p><p>同学提问：哪一个画面细节最有诗句依据？有没有另一首诗也能配？</p></details><div class="game-card-actions"><button data-game-download="${c.id}">下载图文作品卡 ↓</button><button data-game-remove="${c.id}">移除</button></div></div></article>`;}).join(''):'<p class="game-empty-wall">第一张作品卡，等你把诗句和画面连起来。</p>';
 document.querySelectorAll('[data-game-download]').forEach(b=>b.onclick=()=>downloadGameCard(poetryGame.cards.find(c=>c.id===b.dataset.gameDownload)));document.querySelectorAll('[data-game-remove]').forEach(b=>b.onclick=()=>{poetryGame.cards=poetryGame.cards.filter(c=>c.id!==b.dataset.gameRemove);renderGameCards();gameMessage('已从本轮作品墙移除；已下载的文件保留。');});}
function gameCardHtml(c,imageSrc){const w=findReadingWork(c.workId),e=escapeHtml;return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data: https:; style-src 'unsafe-inline'; base-uri 'none'"><title>诗图作品卡 · ${e(w.s[5])}</title><style>body{max-width:760px;margin:40px auto;padding:0 24px;background:#f8f6f0;color:#293c35;font:16px/1.9 system-ui}img{max-width:100%;max-height:580px;display:block;margin:auto}blockquote{font-size:23px;white-space:pre-line;border-left:3px solid #496654;padding-left:20px;margin:24px 0}small{color:#727d70}p{white-space:pre-wrap;overflow-wrap:anywhere}</style><p><small>诗行山河 · ${c.mode==='poem'?'给诗配图':'给图配诗'} · 学生配对作品</small></p><h1>${e(w.s[5])}</h1><p>${e(workAuthor(w))}</p><img src="${e(imageSrc)}" alt="${e(c.photo.title)}" referrerpolicy="no-referrer"><blockquote>${e(c.quote)}</blockquote><h2>我的配对理由</h2><p>${e(c.reason)}</p>${c.difference?`<h2>不同之处与想象</h2><p>${e(c.difference)}</p>`:''}<h2>图片来源</h2><p>${e(c.photo.kind)} · ${e(c.photo.credit)}</p><h2>邀请同学聊一聊</h2><p>哪一个画面细节最有诗句依据？有没有另一首诗也能配？</p><small>作品由学生选择图片并填写说明，未使用AI评分。现代实景或艺术画面不等于古人所见。网络直链图片需联网加载。</small></html>`;}
async function downloadGameCard(c){if(!c)return;try{const imageSrc=c.photo.origin==='sample'||c.photo.origin==='ai-sample'?resizeGameImage(await loadGameImage(c.photo.src)):c.photo.src;const blob=new Blob([gameCardHtml(c,imageSrc)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='诗图作品卡-'+findReadingWork(c.workId).s[5].replace(/[\\/:*?"<>|]/g,'')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);gameMessage('作品卡已下载为HTML文件。可交给同学用浏览器打开，继续交流。');}catch{gameMessage('作品卡下载失败，图片可能尚未加载完成。请换一张示例或重新上传后再试。');}}
function initPoetryGames(){const requested=new URLSearchParams(location.search).get('work');if(gameWorks().some(w=>w.meta.id===requested))poetryGame.drafts.poem.workId=requested;renderPoetryGames();$('gamesTab').onclick=()=>activeStudioTab('games');const names=['compose','gallery','games'];for(const name of names)$(name+'Tab').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=names.indexOf(name),next=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;activeStudioTab(names[next]);$(names[next]+'Tab').focus();};if(location.hash==='#games')activeStudioTab('games');}
initPoetryGames();
